import csv, json, re, collections
inv = {r['id']: round(float(r['amount']),2) for r in csv.DictReader(open('backoffice/invoices.csv', encoding='utf-8'))}
pays = collections.defaultdict(list)
for r in csv.DictReader(open('backoffice/bank_statement_june.csv', encoding='utf-8')):
    m = re.search(r'inv(?:oice)?[-\s]*(\d{4})', r['memo'], re.I)
    if not m: continue
    i = 'INV-' + m.group(1)
    if i in inv: pays[i].append(round(float(r['amount']),2))
unpaid = sorted(i for i in inv if i not in pays)
dup = sorted(i for i in pays if len(pays[i]) > 1)
mis = [{'id': i, 'invoiced': inv[i], 'paid': p[0]} for i, p in sorted(pays.items()) if len(p) == 1 and p[0] != inv[i]]
json.dump({'unpaid': unpaid, 'duplicated': dup, 'mismatched': mis}, open('reconciliation.json', 'w'), indent=2)
print(open('reconciliation.json').read())
